import{_ as a,C as s,o,c as n,a6 as t,E as i}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/server-coverage.png",f=JSON.parse('{"title":"Server coverage","description":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core or Nitro build instrumented for coverage, even when the tests run in parallel against one backend.","frontmatter":{"title":"Server coverage","description":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core or Nitro build instrumented for coverage, even when the tests run in parallel against one backend.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/server-coverage.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/server-coverage.html"}],["meta",{"property":"og:title","content":"Server coverage | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core or Nitro build instrumented for coverage, even when the tests run in parallel against one backend."}]]},"headers":[],"relativePath":"features/server-coverage.md","filePath":"features/server-coverage.md","lastUpdated":1793044021000}'),l={name:"features/server-coverage.md"};function c(h,e,u,p,g,m){const r=s("DemoExamples");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="server-coverage" tabindex="-1">Server coverage <a class="header-anchor" href="#server-coverage" aria-label="Permalink to &quot;Server coverage&quot;">​</a></h1><p>With an ASP.NET Core or a Nitro backend built for coverage, each test records the backend code it ran: its files, the functions that ran in them and, at the finest granularity, the executed lines. Requests are told apart, so tests running in parallel against one shared backend each keep their own. The browser side is <a href="./code-reach.html">code reach</a>; both feed the <a href="./code-reach.html#on-the-execution-page">execution page</a>, the <a href="./code-reach.html#which-tests-run-a-file">file coverage page</a>, the <a href="./editor-coverage.html">editors</a> and the <a href="./coverage-insights.html">coverage insights</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><ol><li><p>Build the backend for coverage, in the test environment only:</p><ul><li><strong>ASP.NET Core:</strong> add the <code>PiwiTests.Instrumentation.Coverage</code> package to every project whose code you want covered, as its <a href="https://github.com/PiwiTests/piwi/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#readme" target="_blank" rel="noreferrer">README</a> shows, serve it with <code>app.UsePiwiTestLogs()</code> (<a href="/guide/backend-logs.html">backend instrumentation</a>), and build with <code>-p:PiwiCoverage=true</code>. It refuses to start in the Production environment, and <code>PiwiCoverageForbidden</code> makes a build fail when coverage reaches it (<a href="https://github.com/PiwiTests/piwi/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#enabling-it" target="_blank" rel="noreferrer">README</a>).</li><li><strong>Nitro:</strong> with the plugin and the module of <code>@piwitests/instrumentation-nitro</code> in place (<a href="https://github.com/PiwiTests/piwi/tree/main/integrations/nitro#server-coverage" target="_blank" rel="noreferrer">README</a>), set <code>PIWI_COVERAGE_BUILD=true</code> when the server is built (<code>nitro build</code>, or <code>nitro dev</code>). The module then instruments the server&#39;s own code. A coverage build refuses to start where <code>NODE_ENV</code> is <code>production</code>, which <code>nitro build</code> makes it, unless <code>PIWI_TEST_LOGS_DISABLED=false</code> serves it there; <code>PIWI_COVERAGE_FORBIDDEN=true</code> makes a coverage build fail.</li></ul><p>Never ship that build to production: its code runs slower, and its coverage endpoints expose source paths and line numbers.</p></li><li><p>Set the reporter&#39;s <code>coverage.server</code> option, or <code>PIWI_COVERAGE_SERVER</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place.</p></li></ol><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { coverage: { server: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;lines&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }]],</span></span></code></pre></div><p>Against a backend that is not a coverage build, no response names any coverage, so the reporter collects nothing and the option costs nothing: it can stay on, and the build decides.</p><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>coverage.server</code></th><th>Records per test</th></tr></thead><tbody><tr><td><code>files</code></td><td>the backend files that ran, paths only</td></tr><tr><td><code>functions</code></td><td>also the start and end line of each function that ran</td></tr><tr><td><code>lines</code></td><td>also the executed lines</td></tr></tbody></table><p>With <code>functions</code> and <code>lines</code>, each file names the git blob its line numbers refer to. At the end of the run the reporter also sends each backend&#39;s run-level coverage, attributed to no test, with each file&#39;s executable lines at <code>lines</code>: the lines no test runs, in every assembly or every Nitro server file built with coverage, including those whose code never ran. A test whose coverage the backend no longer held, or that could not be collected, is marked incomplete.</p><figure><img src="'+d+'" alt="The backend files one test ran, recorded by line"><figcaption>One test&#39;s backend files, with the lines it ran.</figcaption></figure><p>The backend names the checksum of the source each file was built from. When the file in the reporter&#39;s checkout differs (the backend was built from another commit), the reporter keeps the file&#39;s path but drops its line numbers, which would point at the wrong lines, and marks the test incomplete; the run-level coverage drops them the same way.</p><h2 id="how-it-is-collected" tabindex="-1">How it is collected <a class="header-anchor" href="#how-it-is-collected" aria-label="Permalink to &quot;How it is collected&quot;">​</a></h2><p>Each response names its request&#39;s coverage in an <code>X-Piwi-Coverage</code> header. Once the test ends, outside its time, the reporter asks each backend origin for the coverage its pages and API calls named, several tests per call. The run-level coverage is read as the run&#39;s last test ends, while a Playwright <code>webServer</code> is still up, and the lines and functions the tests&#39; coverage named are added to it. Every answer names the backend process: a random id, which also starts each request id, and when the process started. The run-level coverage is whole only when the process that answers it is the one that served the run&#39;s first requests.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>API calls</strong> through Playwright&#39;s <code>request</code> fixture keep their last response&#39;s coverage only: a redirect&#39;s earlier responses, and a response <code>failOnStatusCode</code> turns into an error, name none.</li><li><strong>One backend per request:</strong> a call the backend makes to another counts there only if it forwards the <code>X-Piwi-Coverage</code> header.</li><li><strong>A restart during the run:</strong> the new process starts with no coverage. Each test&#39;s lines are kept, from its own coverage; what the earlier process ran outside a request (startup, background work) is lost, and a test whose requests it served but the reporter had not yet collected is marked incomplete. The reporter warns, the run&#39;s header reads <em>Coverage incomplete: the backend restarted during the run</em>, and the run&#39;s coverage in the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API</a> names the origin and about when it restarted. A backend unreachable at the end of the run is flagged the same way, with only the tests&#39; lines kept. The commit&#39;s <a href="./combined-coverage.html">combined coverage</a> notes the run, and its <code>e2e</code> suite reads as incomplete unless a complete run of the commit counts beside it. A Nitro development server restarts on every rebuild.</li><li><strong>Run level only:</strong> work outside a request (hosted services, timers started at startup), and work a request started that still runs once the reporter collected its coverage. On ASP.NET Core, lambdas created at startup too (inline minimal API handlers, inline middleware, DI factory lambdas); the methods they call count normally. On Nitro, a module&#39;s top-level code: it runs when the module loads, often inside the first request that reaches its route.</li></ul><p><strong>ASP.NET Core:</strong></p><ul><li><strong>Exclusions:</strong> the coverage build leaves out what coverlet does, read from the project&#39;s coverlet settings (<a href="https://github.com/PiwiTests/piwi/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#what-it-leaves-out" target="_blank" rel="noreferrer">README</a>): an excluded member has no executable lines and no coverage.</li><li>C# and Visual Basic only.</li></ul><p><strong>Nitro:</strong></p><ul><li><strong>The server&#39;s own code only:</strong> the files the build bundles, under the repository, outside <code>node_modules</code>. A dependency Nitro keeps external is not covered. A Nuxt application&#39;s <code>server/</code> code is; its pages and components rendered on the server are not yet.</li><li><strong>Lines are the statements&#39; first lines</strong>, as Istanbul and Vitest count them: a statement spanning several lines counts its first one. A class field&#39;s initializer is not instrumented.</li><li><strong>Callbacks that lose the request&#39;s async context</strong>, such as those a library queues without <code>AsyncResource</code>, count at run level.</li><li>Node only: the Bun, Deno and edge presets are not covered.</li></ul><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>On a large ASP.NET Core and Vue application, the coverage build alone ran within 1% of a normal build, and per-test line coverage added under 10% to its UI tests, with no measurable change in its CPU. The build records the same way at every granularity, so files and functions cost what lines cost. On the sample application, whose suite runs against either backend, a coverage build cost no measurable test time on either, and 5.6% more server CPU on Nitro, 12.5% on ASP.NET Core. <a href="/reference/coverage-cost.html">Coverage cost</a> has every mode, how it was measured, and the prototype figures.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',22)),i(r),e[1]||(e[1]=t('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./code-reach.html">Code reach</a>: the browser side, and where the coverage is read</li><li><a href="./editor-coverage.html">Coverage in the editor</a>: the lines tests ran, in VS Code and the JetBrains IDEs</li><li><a href="/guide/backend-logs.html">Backend instrumentation</a>: the middleware that serves the coverage</li><li><a href="/reference/coverage-cost.html">Coverage cost</a>: what each mode costs</li></ul>',2))])}const b=a(l,[["render",c]]);export{f as __pageData,b as default};
